  AccordionDetails,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Alert,
  IconButton,
  Tooltip,
  Divider
} from '@mui/material';
import {
  VaccinesOutlined,
  ExpandMore,
  Download,
  Print,
  Share,
  Warning,
  CheckCircle,
  Schedule,
  Info,
  Close
} from '@mui/icons-material';
import { format, parseISO, differenceInDays } from 'date-fns';

// Mock data for vaccination records
const mockVaccinationData = {
  student: {
    id: 'STU-2024-001',
    name: 'John Smith',
    grade: 'Grade 10',
    birthDate: '2008-03-15',
    avatar: null
  },
  summary: {
    totalRequired: 12,
    completed: 10,
    overdue: 1,
    upcoming: 3,
    complianceRate: 83
  },
  vaccinationSchedule: [
    {
      id: 1,
      vaccine: 'Hepatitis B',
      doses: [
        { doseNumber: 1, date: '2008-03-16', status: 'completed', provider: 'City Health Center' },
        { doseNumber: 2, date: '2008-05-15', status: 'completed', provider: 'City Health Center' },
        { doseNumber: 3, date: '2008-09-15', status: 'completed', provider: 'City Health Center' }
      ],
      nextDue: null,
      category: 'routine'
    },
    {
      id: 2,
      vaccine: 'DTaP (Diphtheria, Tetanus, Pertussis)',
