    },
    {
      id: 4,
      vaccine: 'MMR (Measles, Mumps, Rubella)',
      doses: [
        { doseNumber: 1, date: '2009-03-15', status: 'completed', provider: 'Pediatric Clinic' },
        { doseNumber: 2, date: '2013-03-15', status: 'completed', provider: 'School Health Clinic' }
      ],
      nextDue: null,
