    },
    {
      id: 5,
      vaccine: 'HPV (Human Papillomavirus)',
      doses: [
        { doseNumber: 1, date: '2023-09-15', status: 'completed', provider: 'School Health Clinic' },
        { doseNumber: 2, date: '2024-03-15', status: 'overdue', provider: 'School Health Clinic' }
      ],
      nextDue: '2024-03-15',
