    },
    {
      id: 6,
      vaccine: 'Tdap (Tetanus, Diphtheria, Pertussis Booster)',
      doses: [
        { doseNumber: 1, date: null, status: 'scheduled', provider: 'School Health Clinic' }
      ],
      nextDue: '2024-07-15',
